Markdown note styles.text:
@mixin markdown-content-styles() {
  white-space: normal;
  overflow-wrap: break-word;

  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    color: constants.$darkBlue;
    margin-top: 0;
    margin-bottom: 0.5rem;
  }
  h1 {
    font-size: 1.375rem;
    font-weight: bold;
  }
  h2 {
    font-size: 1.25rem;
  }
  h3 {
    font-size: 1rem;
  }
  h4,
  h5,
  h6 {
    font-size: 0.75rem;
    font-weight: normal;
  }
  p {
    margin-bottom: 0.5rem;
  }
  strong {
    color: constants.$darkBlue;
    padding-right: 0;
  }
  ol,
  ul {
    padding-left: 1.5rem;
    margin-bottom: 0.5rem;
    li {
      padding: 0;
      p {
        margin-bottom: 0.125rem;
      }
    }
    ol,
    ul {
      margin-bottom: 0.125rem;
    }
  }
  hr {
    margin: 0.5rem 0;
  }
  code {
    color: constants.$orRed;
  }
  pre {
    padding: 0.25rem 0.5rem;
    margin-bottom: 0.5rem;
    code {
      font-size: 0.75rem;
      color: #333;
    }
  }
  img.icon {
    width: 1rem;
    height: 1rem;
  }
  blockquote {
    font-size: 0.75rem;
    padding: 0.25rem 0.5rem;
    margin-bottom: 0.5rem;
    border-left-color: #ccc;
    p {
      margin-bottom: 0;
    }
  }
  table {
    max-width: 100%;
    margin-bottom: 0.5rem;
    thead > tr > th {
      vertical-align: bottom;
      border-top: 0;
      border-bottom: 2px solid #ddd;
    }
    tr > td,
    tr > th {
      padding: 0.25rem;
      vertical-align: top;
      border-top: 1px solid #ddd;
    }
  }
}

Note content styles.text:
@use '../utils/constants';
@use '../utils/mixins';

.note-content {
  font-size: 0.75rem;
  line-height: 1.125rem;
  margin-top: 0.125rem;
  margin-bottom: 0.125rem;

  li {
    padding: 0.125rem 0;
  }

  strong {
    font-weight: bold;
    color: constants.$orRed;
    padding-right: 0.25rem;
  }

  .note-content-value {
    white-space: pre-wrap;
    overflow-wrap: break-word;
    &.markdown-rendered {
      @include mixins.markdown-content-styles;
    }
  }

  .private-contents-icon {
    color: constants.$subtleGray;
    padding-right: 0.25rem;
  }

  .attachment-download-link {
    .glyphicon {
      padding-right: 0.25rem;
    }
  }
}

